546	function buildShareHistory(p, clock, { rootLimit = 8 } = {}) {
547	  const registry = createRegistry({ ttlMs: 100, clock, logPath: p });
548	  registry.setQuota('root', rootLimit);
549	  registry.setQuota('east', 4, 'root');
550	  registry.setQuota('west', 3, 'root');
