552	  registry.declareResource('b', 10, 'east');
553	  registry.declareResource('c', 10, 'west');
554	  registry.declareResource('d', 10, 'west');
555	  registry.declareResource('solo', 1);
556	  const keep = registry.acquire('a', 'h1', 200);
557	  const renewed = registry.acquire('a', 'h2', 40);
558	  const freed = registry.acquire('b', 'h3', 200);
559	  registry.acquire('b', 'gone1', 10);
560	  registry.acquire('d', 'gone2', 20);
561	  const group = registry.acquireAll(['c', 'solo'], 'h5', [60, 70]);
562	  clock.set(30);
563	  registry.renew(renewed.token); // -> 70
564	  registry.release(freed.token);
565	  clock.set(50);
566	  return { registry, keep, renewed, freed, group };
567	}
