// 快照压缩与重启恢复：压缩前后重启的归属、每张凭证的到期时刻与四个累计计数逐项一致，
// 重建不额外累加计数，压缩前签发的凭证依旧作废，快照之后的增量事件照常恢复，
// 同一资源重复列出的成组申请各张凭证独立到期、分别回收，等待请求不跨重启存活。

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRegistry } from '../src/index.js';

function makeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (value) => {
    now = value;
  };
  return clock;
}

const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'cc-lease-'));
process.on('exit', () => {
  try {
    fs.rmSync(tmpRoot, { recursive: true, force: true });
  } catch {
    // best effort
  }
});

function logFile(name) {
  return path.join(tmpRoot, name + '.log');
}

const RESOURCES = ['keep', 'solo', 'freed', 'expired', 'g1', 'g2'];
const STATS_AT_50 = { granted: 6, renewed: 0, released: 1, reclaimed: 0, live: 3 };

function buildHistory(p, clock) {
  const registry = createRegistry({ ttlMs: 100, clock, logPath: p });
  const keep = registry.acquire('keep', 'h1', 100);
  const solo = registry.acquire('solo', 'h2', 60);
  const freed = registry.acquire('freed', 'h3', 100);
  registry.acquire('expired', 'h4', 10);
  const group = registry.acquireAll(['g1', 'g2'], 'h5', [30, 80]);
  clock.set(30);
  assert.equal(registry.release(freed.token), true);
  clock.set(50);
  return { registry, keep, solo, freed, group };
}

const SWEEP_MARKS = [
  [50, ['expired', 'g1']],
  [59, []],
  [60, ['solo']],
  [79, []],
  [80, ['g2']],
  [99, []],
  [100, ['keep']],
  [200, []],
];

const pPlain = logFile('plain');
======
// 等待队列：超时按截止时间组织、行为结果不变；大量等待请求并存时，
// 超时判定与唤醒规划的耗时不得随等待请求数线性（或更差）增长。

import assert from 'node:assert/strict';
import { createRegistry } from '../src/index.js';

function makeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (value) => {
    now = value;
  };
  return clock;
}

function timeoutBehaviour() {
  const clock = makeClock(0);
  const registry = createRegistry({ ttlMs: 1000, clock });
  const boss = registry.acquire('res', 'boss', 1000000);
  const n = 90;
  const budgets = [];
  for (let i = 0; i < n; i += 1) {
    budgets.push(((i * 37) % n) + 1);
  }
  const tickets = [];
  for (let i = 0; i < n; i += 1) {
    tickets.push(registry.acquire('res', 'w' + i, 100, budgets[i]));
    assert.equal(tickets[i].status, 'waiting');
  }
  for (let now = 1; now <= n; now += 1) {
    clock.set(now);
    registry.holder('res');
    for (let i = 0; i < n; i += 1) {
      const expected = budgets[i] <= now ? 'expired' : 'waiting';
      assert.equal(tickets[i].status, expected, 'waiter ' + i + ' at now=' + now);
    }
  }
  assert.deepEqual(registry.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1 });
  assert.equal(registry.cancel(tickets[0].waitId), false);
  const late = registry.acquire('res', 'late', 100, 5000);

