1	// In-process, time bounded lease registry with append-only log persistence
2	// and crash-safe snapshots. Time only moves when the injected clock moves;
3	// nothing expires on its own. Tokens are derived from the injected clock as
4	// well, never from wall time.
5	//
6	// Resources may be declared with a share capacity: several holders then
7	// occupy the same resource at once, each holding one credential per share
8	// with its own independent expiry. An undeclared resource stays a
9	// single-occupancy resource exactly as before. Hierarchical quotas sit above
10	// resources: a parent quota bounds the sum of the shares occupied under every
11	// quota below it (and directly declared resources), and every level is
12	// enforced at once.
13	//
14	// Persistence layout:
15	//   <logPath>           append-only event log, one JSON object per line
16	//   <logPath>.snapshot  last compacted state image (single JSON line)
17	// Startup loads the snapshot (if any) and replays only the events past the
18	// compacted boundary marker. Compaction publishes both files through a
19	// temp-file + fsync + rename sequence, so a failure at any step leaves the
20	// previous snapshot and the previous log usable. Every event carries a
21	// monotonic sequence number; a snapshot found next to an un-exchanged
22	// original log (the log swap died after the snapshot rename) simply skips
23	// the already-folded events by their sequence ids, so each event applies
24	// exactly once regardless of which rename made it to disk.
25	
26	import fs from 'node:fs';
27	import path from 'node:path';
28	
29	const LOG_VERSION = 1;
30	const SNAPSHOT_VERSION = 1;
31	
32	export class LeaseTakenError extends Error {
33	  constructor(resource, holder, requested = undefined, available = undefined) {
34	    super(`lease for resource ${String(resource)} is already held`);
35	    this.name = 'LeaseTakenError';
36	    this.code = LeaseTakenError.code;
37	    this.resource = resource;
38	    this.holder = holder ?? null;
39	    this.requested = requested;
40	    this.available = available;
41	  }
42	}
43	LeaseTakenError.code = 'LEASE_TAKEN';
44	
45	export class QuotaExceededError extends Error {
46	  constructor(quota, holder, requested, available) {
47	    super(`quota ${String(quota)} has no room for ${requested} requested share(s)`);
48	    this.name = 'QuotaExceededError';
49	    this.code = QuotaExceededError.code;
50	    this.quota = quota;
51	    this.holder = holder ?? null;
52	    this.requested = requested;
53	    this.available = available;
54	  }
55	}
56	QuotaExceededError.code = 'QUOTA_EXCEEDED';
57	
58	export class LogFileError extends Error {
59	  constructor(message, cause) {
60	    super(message);
61	    this.name = 'LogFileError';
62	    this.code = LogFileError.code;
63	    this.cause = cause ?? null;
64	  }
65	}
66	LogFileError.code = 'LOG_FILE_ERROR';
67	
68	// Binary min-heap ordered by (expiresAt, insertion order). Expiry heaps are
69	// used three ways: one global heap drives reclamation, each resource gets one
70	// for lazy capacity accounting, and each quota node gets one for lazy quota
71	// accounting. Renewals push fresh nodes and retire the old ones, so reclaiming
72	// expired leases only walks entries that are actually due instead of scanning
73	// the whole table.
74	class ExpiryQueue {
75	  constructor() {
76	    this.nodes = [];
77	  }
78	
79	  get size() {
80	    return this.nodes.length;
81	  }
82	
83	  push(node) {
84	    const nodes = this.nodes;
85	    nodes.push(node);
86	    let i = nodes.length - 1;
87	    while (i > 0) {
88	      const parent = (i - 1) >> 1;
89	      if (expiresBefore(nodes[i], nodes[parent])) {
90	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
91	        i = parent;
92	      } else {
93	        break;
94	      }
95	    }
96	  }
97	
98	  peek() {
99	    return this.nodes[0];
100	  }
101	
102	  pop() {
103	    const nodes = this.nodes;
104	    const top = nodes[0];
105	    const last = nodes.pop();
106	    if (nodes.length > 0) {
107	      nodes[0] = last;
108	      let i = 0;
109	      for (;;) {
110	        const left = i * 2 + 1;
111	        const right = left + 1;
112	        let next = i;
113	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
114	          next = left;
115	        }
116	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
117	          next = right;
118	        }
119	        if (next === i) {
120	          break;
121	        }
122	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
123	        i = next;
124	      }
125	    }
126	    return top;
127	  }
128	}
129	
130	function expiresBefore(a, b) {
131	  if (a.expiresAt !== b.expiresAt) {
132	    return a.expiresAt < b.expiresAt;
133	  }
134	  return a.order < b.order;
135	}
136	
137	// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
138	// requests in deadline order instead of scanning every pending request, so
139	// a large waiting population costs O(expired * log n), never O(n) per call.
140	class DeadlineQueue {
141	  constructor() {
142	    this.nodes = [];
143	  }
144	
145	  get size() {
146	    return this.nodes.length;
147	  }
148	
149	  push(node) {
150	    const nodes = this.nodes;
151	    nodes.push(node);
152	    let i = nodes.length - 1;
153	    while (i > 0) {
154	      const parent = (i - 1) >> 1;
155	      if (deadlineBefore(nodes[i], nodes[parent])) {
156	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
157	        i = parent;
158	      } else {
159	        break;
160	      }
161	    }
162	  }
163	
164	  peek() {
165	    return this.nodes[0];
166	  }
167	
168	  pop() {
169	    const nodes = this.nodes;
170	    const top = nodes[0];
171	    const last = nodes.pop();
172	    if (nodes.length > 0) {
173	      nodes[0] = last;
174	      let i = 0;
175	      for (;;) {
176	        const left = i * 2 + 1;
177	        const right = left + 1;
178	        let next = i;
179	        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
180	          next = left;
181	        }
182	        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
183	          next = right;
184	        }
185	        if (next === i) {
186	          break;
187	        }
188	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
189	        i = next;
190	      }
191	    }
192	    return top;
193	  }
194	}
195	
196	function deadlineBefore(a, b) {
197	  if (a.deadline !== b.deadline) {
198	    return a.deadline < b.deadline;
199	  }
200	  return a.tie < b.tie;
201	}
202	
203	let registrySequence = 0;
204	let atomicFileSequence = 0;
205	
206	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
207	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
208	    throw new TypeError('ttlMs must be a positive finite number');
209	  }
210	  if (typeof clock !== 'function') {
211	    throw new TypeError('clock must be a function');
212	  }
213	
214	  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
215	  const defaultTtlMs = ttlMs;
216	  // resource -> FIFO array of queue positions. A group request listing the
217	  // same resource in several rows occupies one position per row.
218	  const waitQueues = new Map();
219	  // requestId -> group, while the request is still queued.
220	  const pendingGroups = new Map();
221	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq, chain,
222	  // counted }
223	  const leases = new Map();
224	  // Every token this instance knows about, including replayed credentials
225	  // that were already released or reclaimed, so a freshly minted token can
226	  // never reuse a dead credential's string.
227	  const knownTokens = new Set();
228	  // resource -> Set of tokens currently attached to it. A share resource
229	  // usually carries several live credentials; the set makes release and
230	  // reclaim O(1) regardless of how many shares coexist.
231	  const slots = new Map();
232	  // resource -> runtime bookkeeping. Created lazily; an undeclared resource
233	  // is a capacity-1 resource with no quota chain.
234	  const resourceStates = new Map();
235	  // quota id -> { id, parentId, limit, live, heap, resources }. `live` is the
236	  // current share occupation counted against the limit, maintained per share
237	  // grant and released lazily by the quota's own expiry heap.
238	  const quotas = new Map();
239	  // The global expiry heap drives sweep(); resource and quota heaps drive
240	  // lazy, sub-linear availability checks.
241	  const expiryQueue = new ExpiryQueue();
242	  // One node per queued wait request, ordered by wait deadline. Nodes outlive
243	  // their request only until the next lazy pop, flagged `dead`.
244	  const deadlineQueue = new DeadlineQueue();
245	
246	  const counters = {
247	    granted: 0,
248	    renewed: 0,
249	    released: 0,
250	    reclaimed: 0,
251	  };
252	
253	  // Per-instance identity makes tokens unique across registries living in the
254	  // same process; one instance can never present a token another owns.
255	  registrySequence += 1;
256	  const registryId = registrySequence;
257	  let tokenSequence = 0;
258	  let queueOrder = 0;
259	  let deadlineTie = 0;
260	  let requestSequence = 0;
261	  let batchSequence = 0;
262	  // Monotonic id stamped on every persisted event; a snapshot records the
263	  // last id it folded in, so a log still containing the folded prefix (the
264	  // log swap failed) replays those events as no-ops instead of twice.
265	  let eventSeq = 0;
266	
267	  function mintToken(now, seq = tokenSequence) {
268	    // Pure candidate: nothing is committed until the event is on disk, so a
269	    // failed append rolls all the way back. Pids and instance ids can coincide
270	    // after a restart, so skip any sequence that collides with a credential
271	    // reconstructed from the log. The caller threads the sequence through when
