397	  const p = logPath('shares');
398	  const options = {
399	    ttlMs: 100,
400	    capacities: { 'z/a': 4, 'z/b': 4 },
401	    quotas: { z: 4 },
402	  };
403	  const c1 = fakeClock(0);
404	  let r = createRegistry({ ...options, clock: c1, logPath: p });
405	  const kept = r.acquire('z/a', 'h', 100, undefined, 2);
406	  const gone = r.acquire('z/b', 'h', 10, undefined, 2);
407	  c1.set(5);
408	  assert.equal(r.renew(kept[0].token), true); // expires 105 now
409	  assert.equal(r.release(gone[0].token), true);
410	  assert.deepEqual(r.stats(), {
411	    granted: 4, renewed: 1, released: 1, reclaimed: 0, live: 3,
412	  });
413	  assert.equal(r.quotaUsage('z', 'h').used, 3);
414	  r.compact();
415	
416	  // Restart straight from the snapshot; the limits come back from the image
417	  // even without repeating the options.
418	  r = createRegistry({ ttlMs: 100, clock: fakeClock(5), logPath: p });
419	  assert.deepEqual(r.stats(), {
420	    granted: 4, renewed: 1, released: 1, reclaimed: 0, live: 3,
421	  });
422	  assert.deepEqual(r.holders('z/a'), ['h', 'h']);
423	  assert.deepEqual(r.holders('z/b'), ['h']);
424	  assert.equal(r.quotaUsage('z', 'h').used, 3);
425	  assert.equal(r.capacityUsage('z/a').capacity, 4);
426	
427	  // The quota is still enforced against the restored occupancy: three
428	  // shares in use under a limit of four leaves no room for two more.
429	  assert.throws(
430	    () => r.acquire('z/a', 'h', 100, undefined, 2),
431	    QuotaError,
432	  );
433	  // ...and reclaimed shares free it again, one credential at a time.
434	  assert.deepEqual(r.sweep(10), ['z/b']);
435	  assert.equal(r.quotaUsage('z', 'h').used, 2);
436	  const back = r.acquire('z/b', 'h', 100);
437	  assert.equal(back.holder, 'h');
438	  assert.equal(r.quotaUsage('z', 'h').used, 3);
439	  // kept[1] expires at 100, kept[0] and back at 105: one sweep takes all.
440	  assert.deepEqual(r.sweep(105), ['z/a', 'z/a', 'z/b']);
441	  assert.deepEqual(r.sweep(110), []);
442	  assert.equal(r.stats().reclaimed, 4);
443	
444	  // A second compaction round-trips the post-restart state exactly.
445	  r.compact();
446	  const before = r.stats();
447	  r = createRegistry({ ttlMs: 100, clock: fakeClock(110), logPath: p });
448	  assert.deepEqual(r.stats(), before);
449	  assert.equal(r.holder('z/a'), null);
450	  assert.equal(r.quotaUsage('z', 'h').used, 0);
