import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import {
  createRegistry,
  LeaseTakenError,
  QuotaError,
} from '../src/index.js';

function fakeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (value) => {
    now = value;
  };
  clock.advance = (delta) => {
    now += delta;
  };
  return clock;
}

let dir;
test.beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-cap-'));
});
test.afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});
function logPath(name) {
  return path.join(dir, `${name}.log`);
}

test('capacity and quota limits must be positive integers', () => {
  for (const bad of [0, -1, 1.5, NaN, Infinity, '2']) {
    assert.throws(
      () => createRegistry({ ttlMs: 10, clock: fakeClock(0), capacities: { r: bad } }),
      RangeError,
    );
    assert.throws(
      () => createRegistry({ ttlMs: 10, clock: fakeClock(0), quotas: { zone: bad } }),
      RangeError,
    );
  }
  // A Map works too, and valid limits are accepted.
  const r = createRegistry({
    ttlMs: 10,
    clock: fakeClock(0),
    capacities: new Map([['r', 2]]),
    quotas: new Map([['zone', 3]]),
  });
  assert.equal(r.capacityUsage('r').capacity, 2);
  assert.equal(r.quotaUsage('zone', 'h').limit, 3);
  // Unregistered lookups: capacity falls back to the exclusive single share,
  // an unknown quota node reports null.
  assert.deepEqual(r.capacityUsage('plain'), {
    resource: 'plain', capacity: 1, registered: false, used: 0, available: 1,
  });
  assert.equal(r.quotaUsage('nope', 'h'), null);
});

test('share counts must be positive integers and fit the registered capacity', () => {
  const r = createRegistry({
    ttlMs: 10,
    clock: fakeClock(0),
    capacities: { big: 3 },
  });
  for (const bad of [0, -2, 1.5, NaN, Infinity, '2']) {
    assert.throws(() => r.acquire('big', 'h', 10, undefined, bad), RangeError);
    assert.throws(() => r.acquireAll(['big'], 'h', 10, undefined, bad), RangeError);
  }
  // Demand above the registered capacity can never be satisfied.
  assert.throws(() => r.acquire('big', 'h', 10, undefined, 4), RangeError);
  assert.throws(() => r.acquireAll(['big', 'big'], 'h', 10, undefined, 2), RangeError);
  // ...even with a wait budget: it never queues.
  assert.throws(() => r.acquire('big', 'h', 10, 1000, 4), RangeError);
  // Nothing landed.
  assert.deepEqual(r.stats(), {
    granted: 0, renewed: 0, released: 0, reclaimed: 0, live: 0,
  });
  // An unregistered resource has no numeric limit: repeated demand keeps the
  // baseline repeated-listing behaviour instead of raising.
  const leases = r.acquire('plain', 'h', 10, undefined, 2);
  assert.equal(leases.length, 2);
});

test('one credential per share, each with its own expiry', () => {
  const clock = fakeClock(100);
  const r = createRegistry({
    ttlMs: 50,
    clock,
    capacities: { pool: 4 },
  });
  const leases = r.acquire('pool', 'a', 30, undefined, 3);
  assert.equal(leases.length, 3);
  assert.ok(leases.every((l) => l.resource === 'pool' && l.holder === 'a'));
  assert.ok(leases.every((l) => l.expiresAt === 130));
  assert.equal(new Set(leases.map((l) => l.token)).size, 3);
  assert.deepEqual(r.stats(), {
    granted: 3, renewed: 0, released: 0, reclaimed: 0, live: 3,
  });
  assert.deepEqual(r.holders('pool'), ['a', 'a', 'a']);
  assert.deepEqual(r.capacityUsage('pool'), {
    resource: 'pool', capacity: 4, registered: true, used: 3, available: 1,
  });

  // The last share goes to another holder; the request after that fails.
  const fourth = r.acquire('pool', 'b');
  assert.equal(fourth.holder, 'b');
  assert.throws(
    () => r.acquire('pool', 'c'),
    (e) => e instanceof LeaseTakenError && e.code === 'LEASE_TAKEN',
  );
  assert.equal(r.stats().granted, 4);
});

test('the options-object form passes ttl, wait and shares together', () => {
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock, capacities: { pool: 3 } });
  const leases = r.acquire('pool', 'h', { ttlMs: 40, shares: 2 });
  assert.equal(leases.length, 2);
  assert.ok(leases.every((l) => l.expiresAt === 40));
  const one = r.acquire('pool', 'h2', { shares: 1 });
  assert.equal(one.expiresAt, 100); // default ttl, baseline single shape
  const ticket = r.acquire('pool', 'w', { ttlMs: 10, waitMs: 500, shares: 2 });
  assert.equal(ticket.status, 'waiting');
  assert.equal(ticket.resource, 'pool');
  const group = r.acquireAll(['pool'], 'g', { shares: 1, waitMs: 5 });
  assert.equal(group.status, 'waiting');
});

test('releasing or reclaiming one share returns exactly that share', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 10,
    clock,
    capacities: { pool: 3 },
  });
  const leases = r.acquire('pool', 'a', 10, undefined, 3);

  clock.set(5);
  assert.equal(r.release(leases[0].token), true);
  assert.equal(r.stats().live, 2);
  assert.equal(r.capacityUsage('pool').available, 1);
  // The other two credentials are untouched.
  assert.equal(r.renew(leases[1].token), true);
  assert.equal(r.release(leases[0].token), false);

  // Expiry reclaims share by share, in expiry order.
  clock.set(20);
  assert.deepEqual(r.sweep(), ['pool', 'pool']);
  assert.deepEqual(r.stats(), {
    granted: 3, renewed: 1, released: 1, reclaimed: 2, live: 0,
  });
});

test('renew extends only the renewed share', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 10,
    clock,
    capacities: { pool: 2 },
  });
  const [first, second] = r.acquire('pool', 'a', 10, undefined, 2);
  clock.set(8);
  assert.equal(r.renew(first.token), true); // first now expires at 18

  clock.set(10);
  assert.deepEqual(r.sweep(), ['pool']); // only the second share expires
  assert.equal(r.holder('pool'), 'a');
  clock.set(18);
  assert.deepEqual(r.sweep(), ['pool']);
  assert.equal(r.holder('pool'), null);
});

test('a waiter is woken only when its full share demand fits', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 100,
    clock,
    capacities: { pool: 3 },
  });
  const held = r.acquire('pool', 'a', 100, undefined, 3);
  const ticket = r.acquire('pool', 'b', 50, 1000, 2);
  assert.equal(ticket.status, 'waiting');
  assert.equal(ticket.resource, 'pool');

  clock.set(10);
  r.release(held[0].token);
  assert.equal(ticket.status, 'waiting', 'one free share is not enough for two');
  r.release(held[1].token);
  assert.equal(ticket.status, 'granted', 'two free shares fill the whole request');
  assert.equal(ticket.leases.length, 2);
  assert.ok(ticket.leases.every((l) => l.expiresAt === 60));
  assert.equal(r.stats().granted, 5);
});

test('share waiters keep strict fifo order per resource', () => {
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock, capacities: { pool: 2 } });
  const held = r.acquire('pool', 'owner', 100, undefined, 2);
  const first = r.acquire('pool', 'first', 50, 1000, 2); // needs both shares
  const second = r.acquire('pool', 'second', 50, 1000, 1);

  clock.set(10);
  r.release(held[0].token);
  assert.equal(first.status, 'waiting', 'one share is not enough for two');
  assert.equal(second.status, 'waiting', 'the head of the queue blocks the line');
  r.release(held[1].token);
  assert.equal(first.status, 'granted');
  assert.equal(second.status, 'waiting', 'the pool is full again');

  clock.set(60); // first's shares expire at 60
  assert.deepEqual(r.sweep(), ['pool', 'pool']);
  assert.equal(second.status, 'granted');
  assert.ok(second.token); // single-share wake keeps the baseline ticket shape
});

test('quota counts a holder across every level of the hierarchy', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 100,
    clock,
    capacities: { 'zone/a': 10, 'zone/b': 10, 'zone/a/x': 10, other: 10 },
    quotas: { zone: 2 },
  });
  r.acquire('zone/a', 'h');
  r.acquire('zone/b', 'h');
  assert.deepEqual(r.quotaUsage('zone', 'h'), {
    node: 'zone', holder: 'h', limit: 2, used: 2, available: 0,
  });

  // A third share anywhere under zone exceeds the holder's quota, even
  // though capacity is free — and it does not queue.
  let caught;
  assert.throws(
    () => r.acquire('zone/a/x', 'h', 50, 1000),
    (e) => {
      caught = e;
      return e instanceof QuotaError;
    },
  );
  assert.equal(caught.code, 'QUOTA_EXCEEDED');
  assert.equal(QuotaError.code, 'QUOTA_EXCEEDED');
  assert.equal(caught.node, 'zone');
  assert.equal(caught.limit, 2);
  assert.equal(caught.holder, 'h');
  // No share, no counter movement, no queue position.
  assert.equal(r.stats().granted, 2);
  assert.equal(r.holder('zone/a/x'), null);
  assert.throws(() => r.acquire('zone/a/x', 'h'), QuotaError);

  // Another holder is unaffected, and resources outside the node are free.
  r.acquire('zone/a/x', 'other');
  r.acquire('other', 'h');
  assert.equal(r.quotaUsage('zone', 'other').used, 1);
  assert.equal(r.stats().granted, 4);
});

test('nested quotas are checked at every ancestor level', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 100,
    clock,
    capacities: { 'a/b/c': 10, 'a/b/d': 10 },
    quotas: { a: 3, 'a/b': 2 },
  });
  r.acquire('a/b/c', 'h', 100, undefined, 2);
  assert.equal(r.quotaUsage('a/b', 'h').used, 2);
  assert.equal(r.quotaUsage('a', 'h').used, 2);

  // The inner node is full for this holder even though the outer has room.
  assert.throws(
    () => r.acquire('a/b/d', 'h'),
    (e) => e instanceof QuotaError && e.node === 'a/b',
  );
  // A different holder fits under both levels.
  r.acquire('a/b/c', 'h2', 100, undefined, 1);
  assert.equal(r.quotaUsage('a', 'h2').used, 1);
  assert.equal(r.quotaUsage('a/b', 'h2').used, 1);
});

test('quota headroom comes back per released or reclaimed share', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 10,
    clock,
    capacities: { 'z/one': 4, 'z/two': 4 },
    quotas: { z: 2 },
  });
  const leases = r.acquire('z/one', 'h', 10, undefined, 2);
  assert.equal(r.quotaUsage('z', 'h').available, 0);

  assert.equal(r.release(leases[0].token), true);
  assert.equal(r.quotaUsage('z', 'h').available, 1);
  const back = r.acquire('z/two', 'h');
  assert.equal(back.holder, 'h');
  assert.equal(r.quotaUsage('z', 'h').available, 0);

  // Expired-but-unswept shares still count; the sweep returns the headroom.
  clock.set(11);
  assert.throws(() => r.acquire('z/one', 'h'), QuotaError);
  assert.deepEqual(r.sweep(), ['z/one', 'z/two']);
  assert.equal(r.quotaUsage('z', 'h').available, 2);
  const again = r.acquire('z/one', 'h', 10, undefined, 2);
  assert.equal(again.length, 2);
});

test('groups are all-or-nothing under capacity and quota constraints', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 100,
    clock,
    capacities: { 'z/a': 2, 'z/b': 2 },
    quotas: { z: 3 },
  });
  r.acquire('z/a', 'owner', 100, undefined, 2);

  // Capacity short on z/a: LeaseTakenError without a wait budget, nothing held.
  assert.throws(
    () => r.acquireAll(['z/a', 'z/b'], 'h'),
    (e) => e instanceof LeaseTakenError && e.code === 'LEASE_TAKEN',
  );
  assert.equal(r.holder('z/b'), null);
  assert.equal(r.stats().granted, 2);

  // Capacity fits but the holder's quota does not: QuotaError, nothing held.
  r.acquire('z/b', 'h', 100, undefined, 2);
  assert.throws(
    () => r.acquireAll(['z/b', 'z/a'], 'h', 100, undefined, 2),
    (e) => e instanceof QuotaError && e.code === 'QUOTA_EXCEEDED',
  );
  assert.equal(r.holder('z/a'), 'owner');
  assert.equal(r.stats().granted, 4);
  assert.equal(r.quotaUsage('z', 'h').used, 2);
});

test('a queued request is woken when quota headroom frees elsewhere', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 100,
    clock,
    capacities: { 'z/a': 1, 'z/b': 1 },
    quotas: { z: 1 },
  });
  const a = r.acquire('z/a', 'owner');
  // Quota is fine at queue time (h holds nothing); capacity blocks.
  const ticket = r.acquire('z/a', 'h', 50, 1000);
  assert.equal(ticket.status, 'waiting');

  // Meanwhile the holder spends their only quota slot on a sibling resource.
  const hb = r.acquire('z/b', 'h');
  clock.set(10);
  r.release(a.token);
  assert.equal(ticket.status, 'waiting', 'capacity is free but quota is not');
  assert.equal(r.holder('z/a'), null);

  // Freeing the sibling returns the quota headroom and wakes the waiter.
  r.release(hb.token);
  assert.equal(ticket.status, 'granted');
  assert.equal(ticket.holder, 'h');
  assert.equal(r.holder('z/a'), 'h');
  assert.equal(r.quotaUsage('z', 'h').used, 1);
});

test('timed-out and cancelled requests never touch quota or counters', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 100,
    clock,
    capacities: { 'z/a': 1 },
    quotas: { z: 2 },
  });
  const held = r.acquire('z/a', 'owner');
  const expiring = r.acquire('z/a', 'h1', 50, 5);
  const cancelling = r.acquire('z/a', 'h2', 50, 1000);
  assert.equal(expiring.status, 'waiting');
  assert.equal(cancelling.status, 'waiting');

  clock.set(6);
  r.stats(); // observe the deadline
  assert.equal(expiring.status, 'expired');
  assert.equal(r.cancel(cancelling.waitId), true);
  assert.equal(r.quotaUsage('z', 'h1').used, 0);
  assert.equal(r.quotaUsage('z', 'h2').used, 0);
  assert.equal(r.stats().granted, 1);

  r.release(held.token);
  assert.equal(expiring.status, 'expired');
  assert.equal(cancelling.status, 'cancelled');
  assert.equal(r.stats().granted, 1);
});

test('shares, quotas and counters survive restart and compaction item by item', () => {
  const p = logPath('shares');
  const options = {
    ttlMs: 100,
    capacities: { 'z/a': 4, 'z/b': 4 },
    quotas: { z: 4 },
  };
  const c1 = fakeClock(0);
  let r = createRegistry({ ...options, clock: c1, logPath: p });
  const kept = r.acquire('z/a', 'h', 100, undefined, 2);
  const gone = r.acquire('z/b', 'h', 10, undefined, 2);
  c1.set(5);
  assert.equal(r.renew(kept[0].token), true); // expires 105 now
  assert.equal(r.release(gone[0].token), true);
  assert.deepEqual(r.stats(), {
    granted: 4, renewed: 1, released: 1, reclaimed: 0, live: 3,
  });
  assert.equal(r.quotaUsage('z', 'h').used, 3);
  r.compact();

  // Restart straight from the snapshot; the limits come back from the image
  // even without repeating the options.
  r = createRegistry({ ttlMs: 100, clock: fakeClock(5), logPath: p });
  assert.deepEqual(r.stats(), {
    granted: 4, renewed: 1, released: 1, reclaimed: 0, live: 3,
  });
  assert.deepEqual(r.holders('z/a'), ['h', 'h']);
  assert.deepEqual(r.holders('z/b'), ['h']);
  assert.equal(r.quotaUsage('z', 'h').used, 3);
  assert.equal(r.capacityUsage('z/a').capacity, 4);

  // The quota is still enforced against the restored occupancy: three
  // shares in use under a limit of four leaves no room for two more.
  assert.throws(
    () => r.acquire('z/a', 'h', 100, undefined, 2),
    QuotaError,
  );
  // ...and reclaimed shares free it again, one credential at a time.
  assert.deepEqual(r.sweep(10), ['z/b']);
  assert.equal(r.quotaUsage('z', 'h').used, 2);
  const back = r.acquire('z/b', 'h', 100);
  assert.equal(back.holder, 'h');
  assert.equal(r.quotaUsage('z', 'h').used, 3);
  // kept[1] expires at 100, kept[0] and back at 105: one sweep takes all.
  assert.deepEqual(r.sweep(105), ['z/a', 'z/a', 'z/b']);
  assert.deepEqual(r.sweep(110), []);
  assert.equal(r.stats().reclaimed, 4);

  // A second compaction round-trips the post-restart state exactly.
  r.compact();
  const before = r.stats();
  r = createRegistry({ ttlMs: 100, clock: fakeClock(110), logPath: p });
  assert.deepEqual(r.stats(), before);
  assert.equal(r.holder('z/a'), null);
  assert.equal(r.quotaUsage('z', 'h').used, 0);
});

test('a full-log restart and a compacted restart agree item by item', () => {
  const p1 = logPath('full');
  const p2 = logPath('folded');
  const options = {
    ttlMs: 100,
    capacities: { 'z/a': 3, 'z/b': 3 },
    quotas: { z: 4 },
  };
  function seed(p) {
    const c = fakeClock(0);
    const r = createRegistry({ ...options, clock: c, logPath: p });
    r.acquire('z/a', 'h1', 100, undefined, 2);
    const temp = r.acquire('z/b', 'h2', 30, undefined, 2);
    c.set(10);
    r.release(temp[0].token);
    return r;
  }
  seed(p1);
  const compacted = seed(p2);
  compacted.compact();

  const full = createRegistry({ ...options, clock: fakeClock(20), logPath: p1 });
  const folded = createRegistry({ ...options, clock: fakeClock(20), logPath: p2 });
  assert.deepEqual(folded.stats(), full.stats());
  assert.deepEqual(folded.holders('z/a'), full.holders('z/a'));
  assert.deepEqual(folded.holders('z/b'), full.holders('z/b'));
  assert.deepEqual(folded.quotaUsage('z', 'h1'), full.quotaUsage('z', 'h1'));
  assert.deepEqual(folded.quotaUsage('z', 'h2'), full.quotaUsage('z', 'h2'));
  assert.deepEqual(folded.sweep(200), full.sweep(200));
});

test('waiting requests still do not survive a restart', () => {
  const p = logPath('waiters');
  const c = fakeClock(0);
  let r = createRegistry({
    ttlMs: 100,
    clock: c,
    logPath: p,
    capacities: { pool: 1 },
  });
  r.acquire('pool', 'a');
  const ticket = r.acquire('pool', 'b', 50, 1000, 1);
  r.compact();

  r = createRegistry({
    ttlMs: 100,
    clock: fakeClock(0),
    logPath: p,
    capacities: { pool: 1 },
  });
  assert.equal(ticket.status, 'waiting');
  const fresh = r.acquire('pool', 'c', 50, 1000);
  assert.equal(fresh.status, 'waiting');
  assert.deepEqual(r.sweep(200), ['pool']);
  assert.equal(fresh.status, 'granted');
  assert.equal(ticket.status, 'waiting');
});

test('many shares do not degrade acquire, sweep or wake planning', () => {
  const clock = fakeClock(0);
  const r = createRegistry({
    ttlMs: 1000,
    clock,
    capacities: { 'all/pool': 20000, 'all/side': 1 },
    quotas: { all: 30000 },
  });
  // 10k shares in one call, then 5k single-share acquisitions on top.
  const bulk = r.acquire('all/pool', 'a', 1000, undefined, 10000);
  assert.equal(bulk.length, 10000);
  for (let i = 0; i < 5000; i += 1) {
    r.acquire('all/pool', `h${i}`, 1000);
  }
  assert.equal(r.stats().live, 15000);
  assert.equal(r.quotaUsage('all', 'a').used, 10000);

  // Single-share churn against a heavily occupied pool stays cheap.
  for (let i = 0; i < 5000; i += 1) {
    const lease = r.acquire('all/pool', 'churn', 1000);
    assert.equal(r.release(lease.token), true);
  }

  // A waiter behind 15k live shares is planned without scanning them.
  const side = r.acquire('all/side', 's');
  const ticket = r.acquire('all/side', 'w', 100, 100000);
  assert.equal(ticket.status, 'waiting');
  clock.set(500);
  r.release(side.token);
  assert.equal(ticket.status, 'granted');

  // Reclaiming the whole population at once is one sweep in expiry order.
  clock.set(1000);
  const freed = r.sweep();
  assert.equal(freed.length, 15001); // 15k pool shares + the woken side lease
  assert.equal(freed[0], 'all/side'); // earliest expiry first
  assert.equal(freed.filter((x) => x === 'all/pool').length, 15000);
  assert.equal(r.stats().live, 0);
  assert.equal(r.stats().reclaimed, 15001);
});

