test('every quota level keeps its room after a compacted restart', () => {
  const p = logPath('rooms');
  const clock = fakeClock(0);
  buildShareHistory(p, clock);
  clock.set(50);
  const r = createRegistry({ ttlMs: 100, clock: fakeClock(50), logPath: p });

  // At t=50: east 2/4 (keep, renewed), west 1/3 (group c), root 4/8.
  assert.equal(r.acquire('c', 'w2', 100).holder, 'w2'); // west 2, root 5
  assert.equal(r.acquire('d', 'w3', 100).holder, 'w3'); // west 3, root 6
  assertQuotaError(() => r.acquire('c', 'w4', 100), 'west');
  assert.equal(r.acquire('a', 'e2', 100).holder, 'e2'); // east 3, root 7
  assert.equal(r.acquire('a', 'e3', 100).holder, 'e3'); // east 4, root 8
  assertQuotaError(() => r.acquire('b', 'rb', 100), 'east');
  assertQuotaError(() => r.acquire('d', 'rd', 100), 'root');

  // The same usage survives another restart.
  const reopened = createRegistry({ ttlMs: 100, clock: fakeClock(50), logPath: p });
  assert.deepEqual(reopened.stats(), {
    granted: 11, renewed: 1, released: 1, reclaimed: 0, live: 8,
  });
  assertQuotaError(() => reopened.acquire('d', 'rd', 100), 'root');
});

