import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRegistry, QuotaExceededError, LogFileError } from './src/index.js';

function clk(s){let n=s;const f=()=>n;f.set=v=>n=v;return f;}
function sabotage(p){fs.renameSync(p,p+'.bak');fs.mkdirSync(p);}
function restore(p){fs.rmdirSync(p);fs.renameSync(p+'.bak',p);}
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'edge-'));
const lp=n=>path.join(dir,n+'.log');

// 1) failed direct grant rollback leaves capacity+quota usage untouched
{
  const p=lp('direct');
  const r=createRegistry({ttlMs:100,clock:clk(0),logPath:p});
  r.setQuota('q',1); r.declareResource('a',10,'q');
  r.acquire('a','h');
  sabotage(p);
  assert.throws(()=>r.acquire('a','h2'), e=>e.code==='LOG_FILE_ERROR');
  restore(p);
  assert.throws(()=>r.acquire('a','h3'), e=>e instanceof QuotaExceededError && e.code==='QUOTA_EXCEEDED' && e.quota==='q' && e.available===0);
  console.log('1 ok: failed direct grant rolls quota back');
}

// 2) failed waking release rolls lease, queues and quota projection back
{
  const p=lp('wake');
  const clock=clk(0);
  const r=createRegistry({ttlMs:100,clock,logPath:p});
  r.setQuota('q',1); r.declareResource('a',10,'q');
  const hold=r.acquire('a','h');
  const t=r.acquire('a','w',50,1000);
  assert.equal(t.status,'waiting');
  clock.set(10);
  sabotage(p);
  assert.throws(()=>r.release(hold.token), e=>e.code==='LOG_FILE_ERROR');
  restore(p);
  assert.equal(t.status,'waiting');
  assert.throws(()=>r.acquire('a','x'), e=>e instanceof QuotaExceededError); // quota still occupied
  assert.equal(r.release(hold.token),true);
  assert.equal(t.status,'granted');
  assert.equal(t.expiresAt,60);
  console.log('2 ok: failed waking release fully rolls back');
}

// 3) failed sweep write restores popped nodes and projected quota room
{
  const p=lp('sweep');
  const clock=clk(0);
  const r=createRegistry({ttlMs:100,clock,logPath:p});
  r.setQuota('q',1); r.declareResource('a',10,'q');
  r.acquire('a','old',10);
  const t=r.acquire('a','w',50,1000);
  clock.set(10);
  sabotage(p);
  assert.throws(()=>r.sweep(), e=>e.code==='LOG_FILE_ERROR');
  restore(p);
  assert.equal(t.status,'waiting');
