file.content:
// Retire a lease's share occupation exactly once. The record itself stays
// in the table until a sweep deletes it (or a single-occupancy retake), so
// silent lazy retirement is never counted as a reclaim; counters for grants
// and the four cumulative totals never move here.
function retireIfCounted(lease) {
  if (lease !== undefined && lease.counted) {
    lease.counted = false;
    const rs = resourceStates.get(lease.resource);
    rs.live -= 1;
    for (const quota of lease.chain) {
      quota.live -= 1;
    }
  }
}

// Pop every due node of one expiry heap, retiring the share occupation of
// nodes that still describe their current lease. Renewed, released and
// already-retired nodes are discarded without touching a counter.
function expireHeap(heap, now) {
  while (heap.size > 0) {
    const node = heap.peek();
    if (node.expiresAt > now) {
      break;
    }
    heap.pop();
    const lease = leases.get(node.token);
    if (lease === undefined || lease.heapSeq !== node.heapSeq) {
      continue;
    }
    retireIfCounted(lease);
  }
}

function getSlots(resource) {
  let set = slots.get(resource);
  if (set === undefined) {
    set = new Set();
    slots.set(resource, set);
  }
  return set;
}

function addSlot(resource, token) {
  getSlots(resource).add(token);
}

