// or a single-occupancy retake): the record leaves the table, so it is
// purged from every owner's retired set and can never come back even if
// the clock later moves to an earlier reading. Never moves a cumulative
// counter; the caller is responsible for the right counter.
function retirePermanent(lease) {
  if (lease === undefined) {
    return;
  }
  if (lease.counted) {
    lease.counted = false;
    const rs = resourceStates.get(lease.resource);
    rs.live -= 1;
    for (const quota of lease.chain) {
      quota.live -= 1;
    }
  }
  const rs = resourceStates.get(lease.resource);
  if (rs !== undefined) {
    rs.retired.delete(lease.token);
  }
  for (const quota of lease.chain) {
