// a single-occupancy retake): the record leaves the table, so it can never
// come back even if the clock later moves to an earlier reading. Never moves
// a cumulative counter; the caller is responsible for the right counter.
function retirePermanent(lease) {
  if (lease === undefined) {
    return;
  }
  const rs = resourceStates.get(lease.resource);
  if (lease.counted) {
    lease.counted = false;
    rs.live -= 1;
    for (const quota of lease.chain) {
      quota.live -= 1;
    }
  }
  rs.retired.delete(lease.tokenForMaps ?? lease.token);
  for (const quota of lease.chain) {
    quota.retired.delete(lease.tokenForMaps ?? lease.token);
  }
}

