// Permanently remove a lease's share occupation (early release, reclaim,
// a single-occupancy retake, or a replay superseding it). Whether it
// still counts at an owner is decided by that owner's own retired set:
// a lazily retired share already moved the owner's usage and must not move
// it again. Either way the share leaves the table, so it can never revive
// even if the clock later moves to an earlier reading.
function retirePermanent(lease) {
  if (lease === undefined) {
    return;
  }
  const rs = resourceStates.get(lease.resource);
  if (rs !== undefined) {
    if (!rs.retired.has(lease.token)) {
      rs.live -= 1;
    }
    rs.retired.delete(lease.token);
  }
  for (const quota of lease.chain) {
    if (!quota.retired.has(lease.token)) {
      quota.live -= 1;
    }
    quota.retired.delete(lease.token);
  }
}

