// Remove every current node naming `token` from one expiry heap. Used
// when a replay structurally supersedes an expired, unswept lease:
// the stale share never occupied the reconstructed owner table, so its
// node leaves the owner heap without any live-usage movement.
function removeHeapNodes(heap, token) {
  let i = 0;
  while (i < heap.nodes.length) {
    const node = heap.nodes[i];
    const lease = leases.get(node.token);
    if (node.token === token && lease !== undefined && lease.heapSeq === node.heapSeq) {
      heap.nodes.splice(i, 1);
    } else {
      i += 1;
    }
  }
  // Restore the heap invariant in linear time after the removals.
  const nodes = heap.nodes;
  for (let j = (nodes.length >>> 1) - 1; j >= 0; j -= 1) {
    let parent = j;
    for (;;) {
      const left = parent * 2 + 1;
      const right = left + 1;
      let smallest = parent;
      if (left < nodes.length && expiresBefore(nodes[left], nodes[smallest])) {
        smallest = left;
      }
      if (right < nodes.length && expiresBefore(nodes[right], nodes[smallest])) {
        smallest = right;
      }
      if (smallest === parent) {
        break;
      }
      [nodes[parent], nodes[smallest]] = [nodes[smallest], nodes[parent]];
      parent = smallest;
    }
  }
}

